def transform(grid):
    """Recolor maximal uniform rectangles matching the demonstrated 5-6 by 5-9 sizes."""
    h, w = len(grid), len(grid[0])
    marked = [[False] * w for _ in range(h)]
    for r0 in range(h):
        for c0 in range(w):
            color = grid[r0][c0]
            for height in (5, 6):
                r1 = r0 + height - 1
                if r1 >= h:
                    continue
                for width in range(5, 10):
                    c1 = c0 + width - 1
                    if c1 >= w:
                        continue
                    if any(grid[r][c] != color for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
                        continue
                    # Only take the whole maximal rectangle, not a subrectangle
                    # inside a larger same-colored block.
                    if r0 > 0 and all(grid[r0-1][c] == color for c in range(c0, c1+1)): continue
                    if r1+1 < h and all(grid[r1+1][c] == color for c in range(c0, c1+1)): continue
                    if c0 > 0 and all(grid[r][c0-1] == color for r in range(r0, r1+1)): continue
                    if c1+1 < w and all(grid[r][c1+1] == color for r in range(r0, r1+1)): continue
                    for r in range(r0, r1+1):
                        for c in range(c0, c1+1): marked[r][c] = True
    return [[4 if marked[r][c] else grid[r][c] for c in range(w)] for r in range(h)]
